code.C:
#include <stdio.h>
#include <math.h>
int main() {
    long long n; if (scanf("%lld", &n) != 1) return 0;
    long long k = (long long)sqrt(n);
    if (k * (k + 1) == n) printf("YES\n");
    else printf("NO\n");
    return 0;
}

