}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long n = sc.nextLong();
            long k = (long)Math.sqrt(n);
            System.out.println(k * (k + 1) == n ? "YES" : "NO");
        }
    }
}

